import sys
import subprocess
import hashlib
import re

def generate_hex_token(output_bytes):
    return hashlib.sha256(output_bytes).hexdigest()[:16].lower()

def process_commands(input_file, output_file):
    with open(input_file, 'r') as f:
        commands = [line.strip() for line in f if line.strip() and not line.strip().startswith('#')]

    data = []
    for cmd in commands:
        try:
            result = subprocess.run(cmd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=False)
            output_bytes = result.stdout + result.stderr
            token = generate_hex_token(output_bytes)
            data.append({
                'command': cmd,
                'exit_code': result.returncode,
                'output_bytes': len(output_bytes),
                'token': token,
                'output': output_bytes
            })
        except Exception as e:
            data.append({
                'command': cmd,
                'exit_code': -1,
                'output_bytes': 0,
                'token': generate_hex_token(b''),
                'output': b'Error executing command'
            })

    html = f"""<!DOCTYPE html>
<html>
<head>
    <title>Run Report</title>
    <style>
        table {{
            border-collapse: collapse;
            width: 100%;
        }}
        th, td {{
            border: 1px solid #ddd;
            padding: 8px;
            text-align: left;
        }}
        th {{
            background-color: #f2f2f2;
        }}
        tr:nth-child(even) {{
            background-color: #f9f9f9;
        }}
    </style>
</head>
<body>
    <h1>Run report</h1>
    <table>
        <tr>
            <th>Command</th>
            <th>Exit code</th>
            <th>Output bytes</th>
            <th>Token</th>
            <th>Output</th>
        </tr>
"""
    for entry in data:
        html += f"""
        <tr>
            <td>{entry['command']}</td>
            <td>{entry['exit_code']}</td>
            <td>{entry['output_bytes']}</td>
            <td>{entry['token']}</td>
            <td><pre>{entry['output'].decode('latin-1', errors='replace')}</pre></td>
        </tr>
"""
    html += """
    </table>
</body>
</html>
"""
    with open(output_file, 'w') as f:
        f.write(html)

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python runreport.py <input_commands_file> <output_html_file>")
        sys.exit(1)
    process_commands(sys.argv[1], sys.argv[2])
